DELIMITER $$
CREATE PROCEDURE sp_level(IN p_sno CHAR(5),
  IN p_cno CHAR(3), OUT p_lv VARCHAR(4))
BEGIN
  DECLARE g INT DEFAULT NULL;
  SELECT grade INTO g FROM sc
    WHERE sno = p_sno AND cno = p_cno;
  IF g IS NULL THEN SET p_lv = '无成绩';
  ELSEIF g >= 90 THEN SET p_lv = '优秀';
  ELSEIF g >= 75 THEN SET p_lv = '良好';
  ELSEIF g >= 60 THEN SET p_lv = '及格';
  ELSE SET p_lv = '不及格';
  END IF;
END $$
DELIMITER ;
CALL sp_level('S01', 'C02', @a);
CALL sp_level('S03', 'C01', @b);
SELECT @a, @b;

DELIMITER $$
CREATE PROCEDURE sp_adjust(IN p_cat VARCHAR(10),
  IN p_rate DECIMAL(4,2), OUT p_n INT)
BEGIN
  UPDATE goods SET price = price * p_rate
    WHERE category = p_cat;
  SET p_n = ROW_COUNT();
END $$
CREATE PROCEDURE sp_stock(IN p_gno CHAR(4),
  OUT p_msg VARCHAR(10))
BEGIN
  DECLARE s INT DEFAULT NULL;
  SELECT stock INTO s FROM goods
    WHERE gno = p_gno;
  CASE
    WHEN s IS NULL THEN SET p_msg = '无此商品';
    WHEN s = 0 THEN SET p_msg = '缺货';
    WHEN s < 10 THEN SET p_msg = '库存紧张';
    ELSE SET p_msg = '充足';
  END CASE;
END $$
DELIMITER ;
CALL sp_adjust('数码', 0.9, @n);
CALL sp_stock('G03', @m);
SELECT @n, @m;

