DELIMITER $$
CREATE PROCEDURE sp_sum(IN n INT, OUT s INT)
BEGIN
  DECLARE i INT DEFAULT 1;
  SET s = 0;
  WHILE i <= n DO
    SET s = s + i;
    SET i = i + 2;
  END WHILE;
END $$
DELIMITER ;
CALL sp_sum(10, @s);
SELECT @s;

DELIMITER $$
CREATE PROCEDURE sp_rep(INOUT x INT)
BEGIN
  REPEAT
    SET x = x * 2;
  UNTIL x > 10
  END REPEAT;
END $$
DELIMITER ;
SET @r = 20;
CALL sp_rep(@r);
SELECT @r;

DELIMITER $$
CREATE PROCEDURE sp_loop(OUT t INT)
BEGIN
  DECLARE i INT DEFAULT 0;
  SET t = 0;
  lp: LOOP
    SET i = i + 1;
    IF i > 6 THEN LEAVE lp; END IF;
    IF i % 3 = 0 THEN ITERATE lp; END IF;
    SET t = t + i;
  END LOOP lp;
END $$
DELIMITER ;
CALL sp_loop(@t);
SELECT @t;

