DELIMITER $$
CREATE FUNCTION fn_avg(p_sno CHAR(5))
  RETURNS DECIMAL(5,1)
  READS SQL DATA
BEGIN
  DECLARE a DECIMAL(5,1);
  SELECT ROUND(AVG(grade), 1) INTO a
    FROM sc WHERE sno = p_sno;
  IF a IS NULL THEN SET a = 0; END IF;
  RETURN a;
END $$
DELIMITER ;
SELECT sno, sname, fn_avg(sno) AS 平均成绩
  FROM student;
DROP FUNCTION fn_avg;

DELIMITER $$
CREATE PROCEDURE sp_low(OUT p_list VARCHAR(200))
BEGIN
  DECLARE v_name VARCHAR(30);
  DECLARE done INT DEFAULT 0;
  DECLARE cur CURSOR FOR
    SELECT gname FROM goods
    WHERE stock < 10 ORDER BY gno;
  DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = 1;
  SET p_list = '';
  OPEN cur;
  FETCH cur INTO v_name;
  WHILE done = 0 DO
    IF p_list = '' THEN
      SET p_list = v_name;
    ELSE
      SET p_list = CONCAT(p_list, ',', v_name);
    END IF;
    FETCH cur INTO v_name;
  END WHILE;
  CLOSE cur;
END $$
DELIMITER ;
CALL sp_low(@s);
SELECT @s;
